const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const pt = ee.Geometry.Point([-121.154, 45.620]); // Dallesport, WA approx
    const region = pt.buffer(5000); // 5 km buffer
    const start = ee.Date('2022-07-01');
    const end = ee.Date('2022-08-01'); // exclusive
    const threshF = 95.0;
    const K_to_F = function(k) { return (k - 273.15) * 9/5 + 32; };

    const getInfo = (eeObj) => new Promise((resolve, reject) => eeObj.getInfo(resolve, reject));

    // 2. Data Acquisition & Check (Primary: GRIDMET daily max air temp)
    let used = 'GRIDMET';
    let band = 'tmmx';
    let scale = 4000;

    let col = ee.ImageCollection('IDAHO_EPSCOR/GRIDMET')
      .filterDate(start, end)
      .select([band]);

    let size = await getInfo(col.size());
    console.log(`Region center: lon=-121.154, lat=45.620; buffer_km=5`);
    console.log(`GRIDMET Images: ${size}`);

    // Fallback if empty: ERA5-Land Daily Aggregated max 2m temperature
    if (!size || size === 0) {
      used = 'ERA5-LAND';
      band = 'temperature_2m_max';
      scale = 9000;
      col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
        .filterDate(start, end)
        .select([band]);
      size = await getInfo(col.size());
      console.log(`ERA5-LAND Images: ${size}`);
      if (!size || size === 0) {
        console.log(`No images found for July 2022 in both datasets.`);
        console.log('C1: Empty Collection');
        return;
      }
    }

    // 3. Processing: Max over time, pixel count check
    const maxOverTime = col.max(); // per-pixel max across July
    const countDict = maxOverTime.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
    });
    const pixCount = await getInfo(countDict.get(band));
    if (!pixCount || pixCount === 0) {
      console.log(`Valid pixels after processing: 0`);
      console.log('C2: No Valid Pixels');
      return;
    }

    // 4. Calculation: Regional max and convert to F
    const maxDict = maxOverTime.reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
    });
    const maxK = await getInfo(maxDict.get(band));
    if (maxK === null || maxK === undefined || isNaN(maxK)) {
      console.log(`Max value invalid: ${maxK}`);
      console.log('C3: Calculation Failure');
      return;
    }
    const maxF = K_to_F(maxK);

    // 5. Validation & Final Answer
    console.log(`Dataset used: ${used}, Valid pixels: ${pixCount}, scale_m: ${scale}`);
    console.log(`Max daily Tmax (K): ${maxK.toFixed(2)}, (F): ${maxF.toFixed(2)}`);
    console.log(`Threshold (F): ${threshF.toFixed(1)}`);
    if (maxF >= threshF) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
